-- 483: Original BrillaPrep Cambridge A-Level Biology (9700) Biotechnology and Gene Technology questions (batch alevel-bio-sprint2-001).
-- Curriculum-aligned practice content; not official Cambridge International or WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_483_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_483_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_biotech_s2_001', 'topic_alevel_bio_biotech', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'What is the role of the enzyme DNA ligase in genetic engineering?', 'multiple_choice', NULL, '["A. It cuts DNA at specific recognition sequences","B. It separates the two strands of DNA by breaking hydrogen bonds","C. It joins DNA fragments together by forming phosphodiester bonds in the sugar–phosphate backbone","D. It synthesises a complementary DNA copy from an mRNA template"]', 'C', 'After a restriction endonuclease cuts both the plasmid vector and the donor DNA to give complementary sticky ends, DNA ligase seals the sugar–phosphate backbone by catalysing the formation of phosphodiester bonds, producing recombinant DNA. Cutting is the job of restriction enzymes; strand separation is achieved by heat in PCR or by helicase in living cells; and copying mRNA into DNA is the role of reverse transcriptase. Therefore the correct answer is C: It joins DNA fragments together by forming phosphodiester bonds in the sugar–phosphate backbone.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_biotech_s2_002', 'topic_alevel_bio_biotech', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which feature makes bacteria such as Escherichia coli useful as hosts for producing human proteins?', 'multiple_choice', NULL, '["A. They contain no DNA of their own, so the human gene is the only DNA present","B. They are eukaryotes, so they process proteins exactly as human cells do","C. They lack ribosomes, so no unwanted bacterial proteins are made","D. They contain plasmids that can be modified as vectors, and they reproduce rapidly so large quantities of the gene product are made quickly"]', 'D', 'Bacteria carry small circular plasmids that are easy to cut, modify with a foreign gene and reinsert, and they divide as often as every 20 minutes in fermenters, amplifying the gene and its protein product at industrial scale. Bacteria certainly have their own DNA; they are prokaryotes — a genuine limitation, because they cannot always add the carbohydrate groups found on human glycoproteins; and they must have ribosomes to translate the human gene at all. Therefore the correct answer is D: They contain plasmids that can be modified as vectors, and they reproduce rapidly so large quantities of the gene product are made quickly.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_biotech_s2_003', 'topic_alevel_bio_biotech', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In the polymerase chain reaction, why must two short DNA primers be added to the reaction mixture?', 'multiple_choice', NULL, '["A. DNA polymerase can only add nucleotides to an existing strand, so the primers anneal to the template and mark the two ends of the region to be copied","B. The primers cut the template DNA into fragments that are easier to copy","C. The primers supply the energy needed for DNA synthesis","D. The primers sterilise the mixture by binding any contaminating DNA"]', 'A', 'Taq DNA polymerase needs a free 3′ end to extend, and the two primers — complementary to sequences flanking the target region on opposite strands — provide those starting points and define exactly which stretch of DNA is amplified. Primers are not enzymes, so they cannot cut DNA; the energy for synthesis comes from the nucleotide triphosphates themselves; and specificity comes from choosing primer sequences unique to the target, not from binding contaminants. Therefore the correct answer is A: DNA polymerase can only add nucleotides to an existing strand, so the primers anneal to the template and mark the two ends of the region to be copied.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_biotech_s2_004', 'topic_alevel_bio_biotech', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which statement correctly states an advantage of producing human insulin from genetically engineered bacteria rather than extracting insulin from pigs or cattle?', 'multiple_choice', NULL, '["A. Animal insulin works faster than human insulin because it is a stronger molecule","B. The bacterial product is identical to human insulin, so it is less likely to trigger an immune response and can be produced in large, pure quantities","C. Bacterial insulin does not need to be purified before medical use","D. GM bacteria produce insulin only when patients need it, avoiding storage"]', 'B', 'Animal insulins differ from human insulin by a few amino acids, so some patients developed allergic reactions and antibody resistance; recombinant human insulin has exactly the human amino acid sequence, avoiding this, and fermenters yield unlimited, consistent and ethically uncontroversial supplies. Animal insulin is not “stronger”; every pharmaceutical protein must be rigorously purified from the bacterial culture; and the bacteria produce insulin during fermentation, not in response to patient demand. Therefore the correct answer is B: The bacterial product is identical to human insulin, so it is less likely to trigger an immune response and can be produced in large, pure quantities.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_biotech_s2_005', 'topic_alevel_bio_biotech', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In gel electrophoresis of DNA, why do the fragments migrate towards the positive electrode (anode), and why do the smallest fragments travel furthest?', 'multiple_choice', NULL, '["A. DNA is positively charged because of its nitrogenous bases, and longer fragments carry more charge so move faster","B. Fragments move by simple diffusion, so the distance travelled is random and unrelated to size","C. DNA is negatively charged because of its phosphate groups, so it is attracted to the anode, and shorter fragments move through the pores of the agarose gel faster than longer ones","D. DNA is repelled by the negative electrode because the gel itself is positively charged"]', 'C', 'Every phosphate group in the DNA backbone carries a negative charge, so all fragments — regardless of length — are drawn towards the anode when the electric field is applied. The agarose gel acts as a molecular sieve: short fragments thread through its pores more easily and travel further in a given time, separating the sample by size. Charge per unit length is the same for all fragments, movement is driven by the field rather than random diffusion, and the gel matrix is neutral. Therefore the correct answer is C: DNA is negatively charged because of its phosphate groups, so it is attracted to the anode, and shorter fragments move through the pores of the agarose gel faster than longer ones.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
CREATE TABLE _migration_483_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _migration_483_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_483_guard;
INSERT INTO _migration_483_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_483_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_483_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_483_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_483_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_483_guard;
INSERT INTO _migration_483_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_483_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 5 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_483_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 5 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_483_expected e ON e.id = q.id) = 5 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_483_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
DROP TABLE _migration_483_guard;
